class Solution {
public:
    void help(TreeNode* root, int &val, int &depth, int curr){
        if(!root || curr>depth)
            return;

        if(curr==depth-1){
            TreeNode* tempLeft=new TreeNode(val);
            TreeNode* tempRight=new TreeNode(val);
            tempLeft->left=root->left;
            tempRight->right=root->right;
            root->left=tempLeft;
            root->right=tempRight;
        }

        help(root->left, val, depth, curr+1);
        help(root->right, val, depth, curr+1);
    }

    TreeNode* addOneRow(TreeNode* root, int val, int depth) {
        if(depth==1){
           auto temp=new TreeNode(val);
            temp->left=root;
            return temp;
        }

        help(root, val, depth, 1);
        return root;
    }
};

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
public class Solution {
    public TreeNode addOneRow(TreeNode t, int v, int d) {
        if (d == 1) {
            TreeNode n = new TreeNode(v);
            n.left = t;
            return n;
        }
        insert(v, t, 1, d);
        return t;
    }

    public void insert(int val, TreeNode node, int depth, int n) {
        if (node == null)
            return;
        if (depth == n - 1) {
            TreeNode t = node.left;
            node.left = new TreeNode(val);
            node.left.left = t;
            t = node.right;
            node.right = new TreeNode(val);
            node.right.right = t;
        } else {
            insert(val, node.left, depth + 1, n);
            insert(val, node.right, depth + 1, n);
        }
    }
}

/**
